package org.vvs.valimbavaka.feature.transfer.domain;

/** Why the stock moved between two locations; it gives the number prefix and the initial status of the transfer. */
public enum TransferOrigin {
    /** Generated by the opening of the day (JR-01, TRF-02). */
    MORNING("TRF", "Transfert du matin"),
    /** Entered by hand between two locations. */
    MANUAL("TRF", "Transfert"),
    /** Unsold articles sent back, e.g. from the store to the warehouse (TRF-03). */
    RETURN("RET", "Retour de stock");

    private final String numberPrefix;
    private final String label;

    TransferOrigin(String numberPrefix, String label) {
        this.numberPrefix = numberPrefix;
        this.label = label;
    }

    /** {@code RET} for a return, {@code TRF} otherwise: each prefix has its own sequence. */
    public String numberPrefix() {
        return numberPrefix;
    }

    /** Label shown in the journal. */
    public String label() {
        return label;
    }

    /** A return keeps its dedicated status; any other transfer is validated on recording. */
    public TransferStatus initialStatus() {
        return this == RETURN ? TransferStatus.RETURN : TransferStatus.VALIDATED;
    }
}
